# Path: PC_ENGINE/sync/sovereign_sync.py\nfrom __future__ import annotations\n\nimport hashlib\nimport json\nimport os\nimport socket\nimport time\nfrom dataclasses import dataclass\nfrom pathlib import Path\nfrom typing import Any\n\nimport requests\n\nSYNC_SCHEMA_VERSION = 1\nDEFAULT_ARTIFACTS = (\n    "radar/state_signature_learning.jsonl",\n    "radar/state_outcomes.jsonl",\n    "radar/l2_oos_validation.json",\n    "radar/capital_opportunities.jsonl",\n    "research/knowledge.jsonl",\n)\n\n@dataclass(frozen=True)\nclass SyncConfig:\n    enabled: bool = False\n    supabase_url: str = ""\n    supabase_key_env: str = "VST_SYNC_SUPABASE_KEY"\n    node_id: str = ""\n    owner_id: str = "andre"\n    interval_hours: int = 24\n    max_artifact_bytes: int = 5 * 1024 * 1024\n\n    @classmethod\n    def from_mapping(cls, raw: dict[str, Any] | None, owner_id: str = "andre") -> "SyncConfig":\n        raw = raw if isinstance(raw, dict) else {}\n        return cls(\n            enabled=bool(raw.get("enabled", False)),\n            supabase_url=str(raw.get("supabase_url", "")).strip().rstrip("/"),\n            supabase_key_env=str(raw.get("supabase_key_env", "VST_SYNC_SUPABASE_KEY")),\n            node_id=str(raw.get("node_id", "")).strip() or socket.gethostname().strip() or "node",\n            owner_id=str(raw.get("owner_id", owner_id)).strip().lower() or "andre",\n            interval_hours=max(1, int(raw.get("interval_hours", 24))),\n            max_artifact_bytes=max(64 * 1024, int(raw.get("max_artifact_bytes", 5 * 1024 * 1024))),\n        )\n\nclass SovereignLearningSync:\n    """Optional learning sync. Local runtime remains authoritative."""\n\n    def __init__(self, data_root: str | Path, config: SyncConfig | dict[str, Any] | None = None):\n        self.data_root = Path(data_root)\n        self.config = config if isinstance(config, SyncConfig) else SyncConfig.from_mapping(config)\n        self.state_path = self.data_root / "sync" / "learning_sync_state.json"\n        self.state_path.parent.mkdir(parents=True, exist_ok=True)\n\n    def _key(self) -> str:\n        return os.getenv(self.config.supabase_key_env, "").strip()\n\n    def enabled(self) -> bool:\n        return bool(self.config.enabled and self.config.supabase_url and self._key())\n\n    def status(self) -> dict[str, Any]:\n        state = self._read_state()\n        return {\n            "schema_version": SYNC_SCHEMA_VERSION,\n            "enabled": self.config.enabled,\n            "configured": bool(self.config.supabase_url and self._key()),\n            "active": self.enabled(),\n            "node_id": self.config.node_id,\n            "owner_id": self.config.owner_id,\n            "last_pull_ts": state.get("last_pull_ts"),\n            "last_push_ts": state.get("last_push_ts"),\n            "last_error": state.get("last_error"),\n            "artifacts_pushed": state.get("artifacts_pushed", 0),\n            "artifacts_pulled": state.get("artifacts_pulled", 0),\n        }\n\n    def _read_state(self) -> dict[str, Any]:\n        try:\n            value = json.loads(self.state_path.read_text(encoding="utf-8"))\n            return value if isinstance(value, dict) else {}\n        except (OSError, ValueError):\n            return {}\n\n    def _write_state(self, value: dict[str, Any]) -> None:\n        tmp = self.state_path.with_suffix(".tmp")\n        tmp.write_text(json.dumps(value, ensure_ascii=False, indent=2, sort_keys=True) + "\n", encoding="utf-8")\n        tmp.replace(self.state_path)\n\n    @staticmethod\n    def _sha256(data: bytes) -> str:\n        return hashlib.sha256(data).hexdigest()\n\n    def _collect(self, artifacts: tuple[str, ...] = DEFAULT_ARTIFACTS) -> list[dict[str, Any]]:\n        rows = []\n        for relative in artifacts:\n            path = self.data_root / relative\n            if not path.exists() or not path.is_file():\n                continue\n            size = path.stat().st_size\n            if size > self.config.max_artifact_bytes:\n                continue\n            data = path.read_bytes()\n            rows.append({\n                "artifact": relative.replace("\\", "/"),\n                "sha256": self._sha256(data),\n                "bytes": len(data),\n                "content": data.decode("utf-8", errors="replace"),\n                "updated_at": int(path.stat().st_mtime),\n            })\n        return rows\n\n    def _headers(self) -> dict[str, str]:\n        key = self._key()\n        return {"apikey": key, "Authorization": f"Bearer {key}", "Content-Type": "application/json"}\n\n    def _table_url(self) -> str:\n        return f"{self.config.supabase_url}/rest/v1/shared_learning_artifacts"\n\n    def push(self, artifacts: tuple[str, ...] = DEFAULT_ARTIFACTS) -> dict[str, Any]:\n        if not self.enabled():\n            return {"ok": False, "status": "DISABLED", "pushed": 0}\n        pushed = 0\n        try:\n            for row in self._collect(artifacts):\n                payload = {\n                    "owner_id": self.config.owner_id,\n                    "artifact": row["artifact"],\n                    "sha256": row["sha256"],\n                    "bytes": row["bytes"],\n                    "content": row["content"],\n                    "source_node_id": self.config.node_id,\n                    "updated_at": row["updated_at"],\n                }\n                response = requests.post(\n                    self._table_url(),\n                    headers={**self._headers(), "Prefer": "resolution=merge-duplicates"},\n                    params={"on_conflict": "owner_id,artifact,sha256"},\n                    json=payload,\n                    timeout=15,\n                )\n                response.raise_for_status()\n                pushed += 1\n            state = self._read_state()\n            state.update({"last_push_ts": int(time.time()), "last_error": None, "artifacts_pushed": pushed})\n            self._write_state(state)\n            return {"ok": True, "status": "PUSHED", "pushed": pushed}\n        except (requests.RequestException, OSError, ValueError) as exc:\n            state = self._read_state()\n            state["last_error"] = f"{type(exc).__name__}: {exc}"\n            self._write_state(state)\n            return {"ok": False, "status": "ERROR", "pushed": pushed, "error": state["last_error"]}\n\n    def pull(self) -> dict[str, Any]:\n        if not self.enabled():\n            return {"ok": False, "status": "DISABLED", "pulled": 0}\n        try:\n            response = requests.get(\n                self._table_url(),\n                headers=self._headers(),\n                params={"owner_id": f"eq.{self.config.owner_id}", "order": "updated_at.desc", "limit": 100},\n                timeout=15,\n            )\n            response.raise_for_status()\n            rows = response.json()\n            if not isinstance(rows, list):\n                raise ValueError("sync response must be a list")\n            pulled = 0\n            for row in rows:\n                if not isinstance(row, dict) or row.get("source_node_id") == self.config.node_id:\n                    continue\n                artifact = str(row.get("artifact", "")).replace("\\", "/")\n                if artifact not in DEFAULT_ARTIFACTS:\n                    continue\n                content = str(row.get("content", ""))\n                data = content.encode("utf-8")\n                expected = str(row.get("sha256", ""))\n                if not expected or self._sha256(data) != expected or len(data) > self.config.max_artifact_bytes:\n                    continue\n                target = self.data_root / artifact\n                target.parent.mkdir(parents=True, exist_ok=True)\n                local_digest = self._sha256(target.read_bytes()) if target.exists() else ""\n                if local_digest == expected:\n                    continue\n                remote_ts = int(row.get("updated_at", 0) or 0)\n                local_ts = int(target.stat().st_mtime) if target.exists() else 0\n                if target.exists() and local_ts > remote_ts:\n                    continue\n                tmp = target.with_suffix(target.suffix + ".sync-tmp")\n                tmp.write_bytes(data)\n                tmp.replace(target)\n                pulled += 1\n            state = self._read_state()\n            state.update({"last_pull_ts": int(time.time()), "last_error": None, "artifacts_pulled": pulled})\n            self._write_state(state)\n            return {"ok": True, "status": "PULLED", "pulled": pulled}\n        except (requests.RequestException, OSError, ValueError) as exc:\n            state = self._read_state()\n            state["last_error"] = f"{type(exc).__name__}: {exc}"\n            self._write_state(state)\n            return {"ok": False, "status": "ERROR", "pulled": 0, "error": state["last_error"]}\n\n    def sync(self) -> dict[str, Any]:\n        pull = self.pull()\n        push = self.push()\n        return {"ok": bool(pull.get("ok") and push.get("ok")), "pull": pull, "push": push}\n